result.content:
1. /**
2.  * Boot scene: generates all procedural assets and shows a title screen.
3.  */
4. 
5. import * as Phaser from "phaser";
6. import { generateAllTextures, generatePlayerTextureWithHair } from "../renderers/textures";
7. import { PLAYER_CLASSES, type PlayerClass } from "../systems/classes";
8. import { SKIN_COLOR_OPTIONS, HAIR_STYLE_OPTIONS, HAIR_COLOR_OPTIONS, type CustomAppearance } from "../systems/appearance";
9. import {
10.   getSaveSummary,
11.   hasSave,
12.   loadGame,
13.   saveGame,
14.   type SaveSlotId,
15. } from "../systems/save";
16. import { createCodex } from "../systems/codex";
17. import { createPlayer, type PlayerState, type PlayerStats, POINT_BUY_COSTS, POINT_BUY_TOTAL, calculatePointsSpent } from "../systems/player";
18. import { abilityModifier, rollAbilityScore } from "../systems/dice";
19. import { audioEngine } from "../systems/audio";
20. import { createWeatherState } from "../systems/weather";
21. import { SceneTransitionManager } from "../managers/sceneTransition";
22. import { debugPanelState } from "../config";
23. import { CAMPAIGN_EPILOGUE_CUTSCENE_ID } from "../data/cutscenes";
24. import {
25.   addSettingsControls,
26.   SETTINGS_PANEL_HEIGHT,
27.   SETTINGS_PANEL_WIDTH,
28. } from "../renderers/settings";
29. import {
30.   installSceneAccessibility,
31.   isReducedMotionEnabled,
32. } from "../systems/accessibility";
33. import {
34.   getNewGameCutsceneIds,
35.   getNextPendingCutscene,
36.   queueCutscenes,
37. } from "../systems/cutscenes";
38. import { openMobileTextInput } from "../managers/input";
39. import { SaveSlotManager } from "../managers/saveSlots";
40. import {
41.   calcPanelLayout,
42.   createDimGraphics,
43.   createOverlayContainer,
44.   createPanelGraphics,
45. } from "../utils/ui";
46. import {
47.   moveGridSelection,
48.   type GridNavigationDirection,
49. } from "../systems/layout";
50. 
51. const BOOT_TEXTURE_MEASURE = "2dnd:boot-textures";
52. const BOOT_TEXTURE_START_MARK = `${BOOT_TEXTURE_MEASURE}:start`;
53. const BOOT_TEXTURE_END_MARK = `${BOOT_TEXTURE_MEASURE}:end`;
54. 
55. type CharacterStatMode = "pointbuy" | "random";
56. 
57. interface CharacterStatSelection {
58.   stats: PlayerStats;
59.   mode: CharacterStatMode;
60. }
61. 
62. interface CharacterCreationControlHandlers {
63.   up(): void;
64.   down(): void;
65.   left(): void;
66.   right(): void;
67.   confirm(): void;
68.   cancel(): void;
69. }
70. 
71. export class BootScene extends Phaser.Scene {
72.   private readonly sceneTransitions = new SceneTransitionManager(this);
73.   private saveSlotManager!: SaveSlotManager;
74. 
75.   constructor() {
76.     super({ key: "BootScene" });
77.   }
78. 
79.   preload(): void {
80.     // No external assets to load - we generate everything procedurally
81.   }
82. 
83.   create(): void {
84.     this.sceneTransitions.prepare();
85.     installSceneAccessibility(this);
86.     performance.clearMeasures(BOOT_TEXTURE_MEASURE);
87.     performance.clearMarks(BOOT_TEXTURE_START_MARK);
88.     performance.clearMarks(BOOT_TEXTURE_END_MARK);
89.     performance.mark(BOOT_TEXTURE_START_MARK);
90.     generateAllTextures(this);
91.     performance.mark(BOOT_TEXTURE_END_MARK);
92.     performance.measure(
93.       BOOT_TEXTURE_MEASURE,
94.       BOOT_TEXTURE_START_MARK,
95.       BOOT_TEXTURE_END_MARK,
96.     );
97.     performance.clearMarks(BOOT_TEXTURE_START_MARK);
98.     performance.clearMarks(BOOT_TEXTURE_END_MARK);
99.     this.saveSlotManager = new SaveSlotManager(this, {
100.       load: (slotId) => this.continueGame(slotId),
101.       save: () => ({
102.         ok: false,
103.         code: "unsupported",
104.         message: "Campaigns can only be saved during play.",
105.       }),
106.       onStateChange: () => this.updateTitleDebugState(),
107.     });
108.     this.events.once("shutdown", () => this.saveSlotManager.destroy());
109.     this.showTitleScreen();
110.   }
111. 
112. 
113.   /** Format class info string for the selection panel. */
114.   private formatClassInfo(app: PlayerClass): string {
115.     const boostParts = Object.entries(app.statBoosts)
116.       .map(([k, v]) => `${k.slice(0, 3).toUpperCase()}+${v}`)
117.       .join(", ");
118.     return `${app.playstyle} | ${boostParts} | d${app.hitDie} HP`;
119.   }
120. 
121.   private bindCharacterCreationControls(
122.     handlers: CharacterCreationControlHandlers,
123.   ): void {
124.     const keyboard = this.input.keyboard;
125.     if (!keyboard) {
126.       throw new Error("[BootScene] Keyboard input is unavailable");
127.     }
128.     const boundAt = performance.now();
129.     const bindings: ReadonlyArray<
130.       readonly [string, () => void, repeatable: boolean]
131.     > = [
132.       ["keydown-UP", handlers.up, true],
133.       ["keydown-DOWN", handlers.down, true],
134.       ["keydown-LEFT", handlers.left, true],
135.       ["keydown-RIGHT", handlers.right, true],
136.       ["keydown-ENTER", handlers.confirm, false],
137.       ["keydown-ESC", handlers.cancel, false],
138.     ];
139.     for (const [eventName, handler, repeatable] of bindings) {
140.       keyboard.on(eventName, (event: KeyboardEvent) => {
141.         if (event.timeStamp <= boundAt || (!repeatable && event.repeat)) return;
142.         handler();
143.       });
144.     }
145.   }
146. 
147. 
148.   private showTitleScreen(): void {
149.     this.saveSlotManager.close();
150.     this.children.removeAll(true);
151.     this.tweens.killAll();
152.     this.input.keyboard!.removeAllListeners();
153.     this.updateTitleDebugState();
154.     const cx = this.cameras.main.centerX;
155.     const cy = this.cameras.main.centerY;
156. 
157.     this.cameras.main.setBackgroundColor(0x0a0a1a);
158. 
159.     // Initialize audio on first pointer interaction (browsers require user gesture)
160.     this.input.once("pointerdown", () => {
161.       audioEngine.init();
162.       audioEngine.playTitleMusic();
163.     });
164.     // Also initialize on first keyboard press
165.     this.input.keyboard!.once("keydown", () => {
166.       audioEngine.init();
167.       audioEngine.playTitleMusic();
168.     });
169. 
170.     // ── Favicon / Logo: procedurally draw the D20 die ──
171.     const logoSize = 72;
