486.     ) {
487.       event.preventDefault();
488.       this.moveAction(1);
489.       return;
490.     }
491.     if (event.key === "Home" || event.key === "End") {
492.       event.preventDefault();
493.       this.selectedSlotIndex = event.key === "Home" ? 0 : this.slots.length - 1;
494.       this.selectedActionIndex = 0;
495.       this.render();
496.       return;
497.     }
498.     if (event.key !== "Enter" && event.key !== " ") return;
499.     event.preventDefault();
500.     event.stopImmediatePropagation();
501.     this.scheduleSelectedAction(event.key === " " ? "keyup-SPACE" : "keyup-ENTER");
