   }

   private applyResult(result: SaveActionResult): void {
     this.setStatus(
       result.ok
         ? result.warning ? `${result.message} ${result.warning}` : result.message
         : result.message,
       result.ok,
     );
   }

   private setStatus(message: string, success: boolean): void {
