1. import { expect, type Page } from "@playwright/test";
2. 
3. const GAME_WIDTH = 640;
4. const GAME_HEIGHT = 528;
5. 
6. interface LayoutReportItem {
7.   id: string;
8.   bounds: { x: number; y: number; width: number; height: number };
9. }
10. 
11. interface LayoutReport {
12.   overlapCount: number;
13.   clippingCount: number;
14.   groups: Record<string, { items: LayoutReportItem[] }>;
15. }
16. 
17. async function readLayoutReport(page: Page): Promise<LayoutReport> {
18.   await expect(page.locator("#layout-report")).not.toHaveText("");
19.   return page.locator("#layout-report").evaluate((element) =>
20.     JSON.parse(element.textContent ?? "{}") as LayoutReport
21.   );
22. }
23. 
24. export async function layoutItemCenter(
25.   page: Page,
26.   id: string,
27. ): Promise<{ x: number; y: number }> {
28.   await expect.poll(async () => {
29.     const report = await readLayoutReport(page);
30.     return Object.values(report.groups)
31.       .flatMap((group) => group.items)
32.       .some((item) => item.id === id);
33.   }).toBe(true);
34.   const report = await readLayoutReport(page);
35.   const item = Object.values(report.groups)
36.     .flatMap((group) => group.items)
37.     .find((candidate) => candidate.id === id);
38.   if (!item) throw new Error(`Missing layout item: ${id}`);
39.   return {
40.     x: item.bounds.x + item.bounds.width / 2,
41.     y: item.bounds.y + item.bounds.height / 2,
42.   };
43. }
44. 
