1. import { expect, test, type Page } from "@playwright/test";
2. import { expectCleanLayout } from "./helpers/layout";
3. 
4. async function waitForState(page: Page, text: string): Promise<void> {
5.   await expect(page.locator("#debug-state")).toContainText(text);
6. }
7. 
8. async function pressNavigationKey(page: Page, key: string): Promise<void> {
9.   await page.keyboard.down(key);
10.   await page.waitForTimeout(80);
11.   await page.keyboard.up(key);
12.   await page.waitForTimeout(120);
13. }
14. 
15. async function seedCampaigns(page: Page, includeManual: boolean): Promise<void> {
16.   await page.evaluate(async (manual) => {
17.     const savePath = "/2dnd/src/systems/save.ts";
18.     const saveSlotsPath = "/2dnd/src/systems/saveSlots.ts";
19.     const playerPath = "/2dnd/src/systems/player.ts";
20.     const codexPath = "/2dnd/src/systems/codex.ts";
21.     const weatherPath = "/2dnd/src/systems/weather.ts";
22.     const save = await import(savePath);
23.     const saveSlots = await import(saveSlotsPath);
24.     const player = await import(playerPath);
25.     const codex = await import(codexPath);
26.     const weather = await import(weatherPath);
27.     const stats = {
28.       strength: 10,
29.       dexterity: 10,
30.       constitution: 10,
31.       intelligence: 10,
32.       wisdom: 10,
33.       charisma: 10,
34.     };
35.     save.deleteAllSaveSlots();
36.     const autosave = player.createPlayer("Autosave Hero", stats, "knight");
37.     autosave.progression.pendingCutsceneIds = [];
38.     autosave.progression.pendingFeatureRevealIds = [];
39.     autosave.progression.tutorial.completed = true;
40.     save.saveGame(
41.       autosave,
42.       new Set(),
43.       codex.createCodex(),
44.       autosave.appearanceId,
45.       12,
46.       weather.createWeatherState(),
47.     );
48.     if (manual) {
49.       const manualSave = player.createPlayer("Manual Hero", stats, "wizard");
