 }

 async function seedCampaigns(page: Page, includeManual: boolean): Promise<void> {
   await page.evaluate(async (manual) => {
     const savePath = "/2dnd/src/systems/save.ts";
     const saveSlotsPath = "/2dnd/src/systems/saveSlots.ts";
