node --input-type=module -e '
import { chromium } from "@playwright/test";
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ hasTouch: true, isMobile: true, viewport: { width: 932, height: 430 } });
const page = await context.newPage();
await page.goto("http://127.0.0.1:4174/game.html", { waitUntil: "networkidle" });
await page.evaluate(async () => {
  const { createPlayer } = await import("/src/systems/player.ts");
  const { createCodex } = await import("/src/systems/codex.ts");
  const { saveGame } = await import("/src/systems/save.ts");
  const { createWeatherState } = await import("/src/systems/weather.ts");
  const player = createPlayer("Mobile Hero", { strength: 10, dexterity: 10, constitution: 10, intelligence: 10, wisdom: 10, charisma: 10 });
  saveGame(player, new Set(), createCodex(), player.appearanceId, 0, createWeatherState());
});
await page.reload({ waitUntil: "networkidle" });
await page.waitForFunction(() => document.querySelector("#debug-state")?.textContent?.includes("TITLE_ACTION:continue"));
await page.screenshot({ path: "/Users/mbianchidev/.copilot/session-state/c5779af9-801b-49f8-82e0-6d79942ca77a/files/title-landscape-after.png" });
const report = JSON.parse(await page.locator("#layout-report").textContent() || "{}");
console.log("title layout", report.overlapCount, report.clippingCount, JSON.stringify(report.groups?.["title-menu"]));
const item = report.groups["title-menu"].items.find(entry => entry.id === "title-new-game");
const canvas = await page.locator("canvas").boundingBox();
await page.touchscreen.tap(canvas.x + (item.bounds.x + item.bounds.width / 2) / 640 * canvas.width, canvas.y + (item.bounds.y + item.bounds.height / 2) / 528 * canvas.height);
await page.waitForFunction(() => document.querySelector("#debug-state")?.textContent?.includes("confirm-newGame"));
await page.screenshot({ path: "/Users/mbianchidev/.copilot/session-state/c5779af9-801b-49f8-82e0-6d79942ca77a/files/title-dialog-landscape-after.png" });
await browser.close();
'

