    26	interface TitleMenuButton {
    27	  action: TitleMenuAction;
    28	  background: Phaser.GameObjects.Rectangle;
    29	  label: Phaser.GameObjects.Text;
    30	}
    31	
    32	const ACTION_LAYOUT_IDS: Readonly<Record<TitleMenuActionId, string>> = {
    33	  continue: "title-continue",
    34	  newGame: "title-new-game",
    35	  saveSlots: "title-save-slots",
    36	  settings: "title-settings",
    37	  quit: "title-quit-desktop",
    38	};
    39	
    40	const MENU_TOP = 250;
    41	const MENU_BOTTOM = 520;
    42	const BUTTON_WIDTH = 320;
    43	const MAX_BUTTON_HEIGHT = 64;
    44	const BUTTON_GAP = 4;
    45	
    46	export class TitleMenuManager {
    47	  private container: Phaser.GameObjects.Container | null = null;
    48	  private buttons: TitleMenuButton[] = [];
    49	  private selectedIndex = 0;
    50	  private boundAt = Number.NEGATIVE_INFINITY;
    51	
    52	  constructor(
    53	    private readonly scene: Phaser.Scene,
    54	    private readonly options: TitleMenuOptions,
    55	  ) {}
    56	
    57	  open(): void {
    58	    this.destroy();
    59	    if (this.options.actions.length === 0) {
    60	      throw new Error("[TitleMenuManager] At least one title action is required");
    61	    }
    62	
    63	    const camera = this.scene.cameras.main;
    64	    const availableHeight = MENU_BOTTOM - MENU_TOP;
    65	    const buttonHeight = Math.min(
    66	      MAX_BUTTON_HEIGHT,
    67	      (
    68	        availableHeight
    69	        - BUTTON_GAP * (this.options.actions.length - 1)
    70	      ) / this.options.actions.length,
    71	    );
    72	    const menuHeight = buttonHeight * this.options.actions.length
    73	      + BUTTON_GAP * (this.options.actions.length - 1);
    74	    const startY = MENU_TOP + (availableHeight - menuHeight) / 2;
    75	    const container = createOverlayContainer(
    76	      this.scene,
    77	      "title-menu",
    78	      5,
    79	      {
    80	        x: camera.centerX - BUTTON_WIDTH / 2,
    81	        y: startY,
    82	        width: BUTTON_WIDTH,
    83	        height: menuHeight,
    84	      },
    85	    );
    86	    this.container = container;
    87	    this.buttons = this.options.actions.map((action, index) => {
    88	      const centerY = startY + buttonHeight / 2
    89	        + index * (buttonHeight + BUTTON_GAP);
    90	      return this.createButton(action, index, camera.centerX, centerY, buttonHeight);
    91	    });
    92	    this.selectedIndex = 0;
    93	    this.updateSelection();
    94	    this.boundAt = performance.now();
    95	    this.scene.input.keyboard?.on("keydown", this.handleKeyDown);
    96	  }
    97	
    98	  destroy(): void {
    99	    this.scene.input.keyboard?.off("keydown", this.handleKeyDown);
   100	    this.container?.destroy();
   101	    this.container = null;
   102	    this.buttons = [];
   103	  }
   104	
   105	  getSelectedActionId(): TitleMenuActionId | null {
   106	    return this.buttons[this.selectedIndex]?.action.id ?? null;
   107	  }
   108	
   109	  private createButton(
   110	    action: TitleMenuAction,
   111	    index: number,
   112	    x: number,
   113	    y: number,
   114	    height: number,
   115	  ): TitleMenuButton {
   116	    const background = this.scene.add.rectangle(
   117	      x,
   118	      y,
   119	      BUTTON_WIDTH,
   120	      height,
   121	      0x171c32,
   122	      0.94,
   123	    ).setStrokeStyle(1, 0x59627c, 1);
   124	    const label = this.scene.add.text(
   125	      x,
   126	      action.detail ? y - 9 : y,
   127	      action.label,
   128	      {
   129	        fontSize: action.detail ? "18px" : "17px",
   130	        fontFamily: "monospace",
   131	        color: action.color,
   132	        align: "center",
   133	      },
   134	    ).setOrigin(0.5);
   135	    label.setData("layoutId", ACTION_LAYOUT_IDS[action.id]);
   136	    label.setData("testId", ACTION_LAYOUT_IDS[action.id]);
   137	
   138	    const objects: Phaser.GameObjects.GameObject[] = [background, label];
   139	    if (action.detail) {
   140	      const detail = this.scene.add.text(x, y + 15, action.detail, {
   141	        fontSize: "9px",
   142	        fontFamily: "monospace",
   143	        color: "#8d96ac",
   144	        align: "center",
   145	      }).setOrigin(0.5);
   146	      detail.setData("layoutAuditIgnore", true);
   147	      objects.push(detail);
   148	    }
   149	
   150	    const hitZone = this.scene.add.zone(
   151	      x,
   152	      y,
   153	      BUTTON_WIDTH,
   154	      height,
   155	    ).setInteractive({ useHandCursor: true });
   156	    hitZone.on("pointerover", () => this.select(index));
   157	    hitZone.on("pointerdown", () => {
   158	      this.select(index);
   159	      this.activateSelected();
   160	    });
   161	    objects.push(hitZone);
   162	    this.container?.add(objects);
   163	    return { action, background, label };
   164	  }
   165	
   166	  private readonly handleKeyDown = (event: KeyboardEvent): void => {
   167	    if (event.timeStamp <= this.boundAt || !this.options.canActivate()) return;
   168	    if (
   169	      event.key === "ArrowUp"
   170	      || event.key === "w"
   171	      || event.key === "W"
   172	    ) {
   173	      event.preventDefault();
   174	      this.move(-1);
   175	      return;
   176	    }
   177	    if (
   178	      event.key === "ArrowDown"
   179	      || event.key === "s"
   180	      || event.key === "S"
   181	    ) {
   182	      event.preventDefault();
   183	      this.move(1);
   184	      return;
   185	    }
   186	    if (event.key === "Enter" || event.key === " ") {
   187	      if (event.repeat) return;
   188	      event.preventDefault();
   189	      this.activateSelected();
   190	      return;
   191	    }
   192	    if (event.repeat) return;
   193	    const shortcut = event.key.toLowerCase();
   194	    const index = this.buttons.findIndex(
   195	      ({ action }) => action.shortcut === shortcut,
   196	    );
   197	    if (index < 0) return;
   198	    event.preventDefault();
   199	    this.select(index);
   200	    this.activateSelected();
   201	  };
   202	
   203	  private move(direction: -1 | 1): void {
   204	    this.select(
   205	      (
   206	        this.selectedIndex
   207	        + direction
   208	        + this.buttons.length
   209	      ) % this.buttons.length,
   210	    );
   211	  }
   212	
   213	  private select(index: number): void {
   214	    if (index === this.selectedIndex) return;
   215	    this.selectedIndex = index;
   216	    this.updateSelection();
   217	  }
   218	
   219	  private updateSelection(): void {
   220	    this.buttons.forEach(({ action, background, label }, index) => {
   221	      const selected = index === this.selectedIndex;
   222	      background
   223	        .setFillStyle(selected ? 0x344365 : 0x171c32, 0.96)
   224	        .setStrokeStyle(selected ? 2 : 1, selected ? 0xffd700 : 0x59627c, 1);
   225	      label.setColor(selected ? "#ffd700" : action.color);
   226	    });
   227	    this.options.onSelectionChange();
   228	  }
   229	
   230	  private activateSelected(): void {
   231	    if (!this.options.canActivate()) return;
   232	    this.buttons[this.selectedIndex]?.action.activate();
   233	  }
   234	}
