   create(): void {
     this.sceneTransitions.prepare();
     installSceneAccessibility(this);
     performance.clearMeasures(BOOT_TEXTURE_MEASURE);
     performance.clearMarks(BOOT_TEXTURE_START_MARK);
     performance.clearMarks(BOOT_TEXTURE_END_MARK);
